def count_pseudo_palindromic_paths(root):
 def visit(node,mask):
  if not node:return 0
  mask^=1<<node.val
  if not node.left and not node.right:return int(mask&(mask-1)==0)
  return visit(node.left,mask)+visit(node.right,mask)
 return visit(root,0)

